import React, { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { fetchCompanyJobs, deleteJob, updateJob } from "../Features/JobSlice";
import "../Styles/CompanyJobs.css";
import { useNavigate } from "react-router-dom";

const CompanyJobs = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();

  // Redux data
  const { company } = useSelector((state) => state.companies);
  const { companyJobs, isLoading } = useSelector((state) => state.jobs);

  // Modal edit states
  const [showModal, setShowModal] = useState(false);
  const [editedJob, setEditedJob] = useState({
    jobTitle: "",
    description: "",
    skills: "",
    rate: "",
    rateType: "",
    category: "",
    sector: "",
    payout: "",
  });

  // ====================================
  // FETCH COMPANY JOBS
  // ====================================
  useEffect(() => {
    const email =
      company?.email || JSON.parse(localStorage.getItem("loggedUser"))?.email;

    if (email) dispatch(fetchCompanyJobs(email));
  }, [company, dispatch]);

  // ====================================
  // OPEN EDIT MODAL
  // ====================================
  const openEditModal = (job) => {
    setEditedJob({ ...job }); // مهم جدًا: نسخ وليس نفس الـ object
    setShowModal(true);
  };

  // ====================================
  // HANDLE SAVE JOB
  // ====================================
  const handleSave = () => {
    dispatch(updateJob(editedJob));
    setShowModal(false);
  };

  // ====================================
  // DELETE JOB
  // ====================================
  const handleDelete = (id) => {
    if (window.confirm("Delete this job?")) {
      dispatch(deleteJob(id));
    }
  };

  if (isLoading) return <p>Loading...</p>;

  return (
    <div className="companyjobs-page">
      <h1 className="companyjobs-title">
        My <span className="accent">Posted Jobs</span>
      </h1>

      {/* ADD NEW JOB BUTTON */}
      <button className="add-job-btn" onClick={() => navigate("/post-job")}>
        + Post New Job
      </button>

      {/* NO JOBS */}
      {companyJobs.length === 0 ? (
        <p className="no-jobs">No jobs posted yet.</p>
      ) : (
        companyJobs.map((job) => (
          <div className="job-card" key={job._id}>
            <h3>{job.jobTitle}</h3>
            <p className="org">{job.organization}</p>

            {/* DETAILS */}
            <p className="desc">{job.description}</p>

            <div className="tags">
              <span className="tag">{job.category}</span>
              <span className="tag">{job.sector}</span>
              <span className="tag">{job.rate} OMR</span>
              <span className="tag">{job.rateType}</span>
            </div>

            <p className="skills">
              Skills Required: <strong>{job.skills}</strong>
            </p>

            {job.payout && (
              <p className="payout">
                Payout Terms: <strong>{job.payout}</strong>
              </p>
            )}

            {/* ACTIONS */}
            <div className="job-actions">
              <button onClick={() => openEditModal(job)} className="edit-btn">
                Edit
              </button>

              <button
                onClick={() => handleDelete(job._id)}
                className="delete-btn"
              >
                Delete
              </button>

              <button
                className="applicants-btn"
                onClick={() => navigate(`/applicants-job?jobId=${job._id}`)}
              >
                Applicants 👥
              </button>
            </div>
          </div>
        ))
      )}

      {/* ====================================
          EDIT MODAL
      ==================================== */}
      {showModal && (
        <div className="modal-overlay">
          <div className="modal-box">
            <h2>Edit Job</h2>

            {/* Title */}
            <label>Job Title</label>
            <input
              value={editedJob.jobTitle}
              onChange={(e) =>
                setEditedJob({ ...editedJob, jobTitle: e.target.value })
              }
            />

            {/* Description */}
            <label>Description</label>
            <textarea
              value={editedJob.description}
              onChange={(e) =>
                setEditedJob({ ...editedJob, description: e.target.value })
              }
            />

            {/* Skills */}
            <label>Skills Required</label>
            <input
              value={editedJob.skills}
              onChange={(e) =>
                setEditedJob({ ...editedJob, skills: e.target.value })
              }
            />

            {/* Rate */}
            <label>Rate (OMR)</label>
            <input
              type="number"
              value={editedJob.rate}
              onChange={(e) =>
                setEditedJob({ ...editedJob, rate: e.target.value })
              }
            />

            {/* Rate Type */}
            <label>Rate Type</label>
            <select
              value={editedJob.rateType}
              onChange={(e) =>
                setEditedJob({ ...editedJob, rateType: e.target.value })
              }
            >
              <option value="Per Hour">Per Hour</option>
              <option value="Per Task">Per Task</option>
              <option value="Per Day">Per Day</option>
            </select>

            {/* Payout */}
            <label>Payout</label>
            <input
              value={editedJob.payout || ""}
              onChange={(e) =>
                setEditedJob({ ...editedJob, payout: e.target.value })
              }
            />

            <div className="modal-actions">
              <button className="save-btn" onClick={handleSave}>
                Save
              </button>
              <button
                className="cancel-btn"
                onClick={() => setShowModal(false)}
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CompanyJobs;
